// Oracle: the release modeling_bailing_moe_v3_vl.py's own get_rope_index and
// BailingMoeV3VLRotaryEmbedding run under torch on a 43-token two-image prompt (grids 8x12 and
// 6x6, merge 2).
test "mrope bailing: the body-diagonal table and the selector's angles match torch" {
    const seq: usize = 43;
    const image_token_id: u32 = 157157;
    const tokens: [seq]u32 = .{ 7, 7, 7, 7, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 7, 7, 7, 7, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 157157, 7, 7 };
    var ri = try getRopeIndexBailing(std.testing.allocator, &tokens, &.{ .{ .t = 1, .h = 8, .w = 12 }, .{ .t = 1, .h = 6, .w = 6 } }, image_token_id, 2);
    defer ri.deinit();
    for (0..3) |ax| {
        for (0..seq) |i| try std.testing.expectEqual(golden_pos[ax][i], ri.pos[ax][i]);
    }
    try std.testing.expectEqual(@as(i32, -31), ri.delta);

    var sel: [32]u8 = undefined;
    bailingSelector(&sel, .{ 8, 12, 12 });
    for (0..32) |d| {
        if (d < 24) try std.testing.expectEqual(@as(u8, if (d % 2 == 0) 1 else 2), sel[d]) else try std.testing.expectEqual(@as(u8, 0), sel[d]);
    }
    var inv: [32]f64 = undefined;
    mrope_mod.computeInvFreq(&inv, 64, 1e7);
    var cos: [9 * 64]f32 = undefined;
    var sin: [9 * 64]f32 = undefined;
    mrope_mod.fillCosSin(&cos, &sin, goldenContext(), 0, 1, 9, &inv, &sel, 64, 1);
    for (0..9) |i| {
        for (0..64) |d| {
            try std.testing.expectApproxEqAbs(@as(f64, golden_cos[i][d]), @as(f64, cos[i * 64 + d]), 5e-6);
            try std.testing.expectApproxEqAbs(@as(f64, golden_sin[i][d]), @as(f64, sin[i * 64 + d]), 5e-6);
        }
    }
}
